-- mod-temucraft-costumes: creature displays that can be worn (every walk/run/strafe/jump/swim/combat/cast/
-- sit/mount/loot/sleep/kneel animation present). Made by tools/build_costume_sql.py from tools/animcheck.py.
DROP TABLE IF EXISTS `mod_temucraft_costume_display`;
CREATE TABLE `mod_temucraft_costume_display` (
  `display` INT UNSIGNED NOT NULL,
  `model` VARCHAR(255) NOT NULL DEFAULT '',
  PRIMARY KEY (`display`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
-- the model paths, numbered; then (display, model number)
DROP TEMPORARY TABLE IF EXISTS `tmp_costume_model`;
CREATE TEMPORARY TABLE `tmp_costume_model` (`id` SMALLINT UNSIGNED NOT NULL PRIMARY KEY, `model` VARCHAR(255) NOT NULL);
DROP TEMPORARY TABLE IF EXISTS `tmp_costume`;
CREATE TEMPORARY TABLE `tmp_costume` (`display` INT UNSIGNED NOT NULL PRIMARY KEY, `m` SMALLINT UNSIGNED NOT NULL);
SELECT c.`display`, m.`model` FROM `tmp_costume` c JOIN `tmp_costume_model` m ON m.`id` = c.`m`;
DROP TEMPORARY TABLE `tmp_costume`;
DROP TEMPORARY TABLE `tmp_costume_model`;
